import {getInitializedSimulationRuntime} from '/src/ui/runtime/simulationRuntime'
import {Tokens} from '/src/core/providers/tokens'
import {SectorGrid} from '/src/core/renderables/DetailedRingStreamingSystem/SectorGrid'
import {state} from './profile.browser'

const stats=(values:number[])=>{const s=values.slice().sort((a,b)=>a-b);return {count:s.length,p50:s[15],p95:s[30],max:s[31]}}
export async function diagnoseSectorLru(){
  const c=getInitializedSimulationRuntime()!.container,engine:any=c.get(Tokens.Engine)
  engine.stop()
  const range=SectorGrid.prototype.getSectorsInRange,lookup=SectorGrid.prototype.layerAt
  const calls:{grid:SectorGrid,args:Parameters<SectorGrid['getSectorsInRange']>}[]=[]
  let fast=false,tracking=false,lookups=0,skipped=0,last=new WeakMap<SectorGrid,{index:number,layer:ReturnType<SectorGrid['layerAt']>}>()
  try{
    SectorGrid.prototype.getSectorsInRange=function(...args){calls.push({grid:this,args});return range.apply(this,args)}
    engine.renderFrame();SectorGrid.prototype.getSectorsInRange=range
    if(!calls.length)throw Error('No sector queries captured')
    const snapshot=state(),reference=calls.map(({grid,args})=>JSON.stringify(range.apply(grid,args)))
    SectorGrid.prototype.layerAt=function(index){
      if(tracking)lookups++
      if(fast){
        const recent=last.get(this)
        if(recent&&recent.index===index){if(tracking)skipped++;return recent.layer}
        const layer=lookup.call(this,index);last.set(this,{index,layer});return layer
      }
      return lookup.call(this,index)
    }
    const one=()=>{for(const{grid,args}of calls)range.apply(grid,args)}
    const statsByMode:any={}
    for(const enabled of [false,true]){
      fast=enabled;last=new WeakMap();tracking=true;lookups=0;skipped=0
      const identical=calls.every(({grid,args},i)=>JSON.stringify(range.apply(grid,args))===reference[i])
      statsByMode[enabled?'candidate':'baseline']={lookups,skipped,identical}
      tracking=false;if(!identical)throw Error('Changed sector values/order')
    }
    const samples:{baseline:number[],candidate:number[]}={baseline:[],candidate:[]},repetitions=8
    const measure=(enabled:boolean)=>{fast=enabled;last=new WeakMap();const started=performance.now();for(let i=0;i<repetitions;i++)one();return (performance.now()-started)/repetitions}
    for(let i=0;i<6;i++){measure(false);measure(true);await new Promise(r=>setTimeout(r,0))}
    for(let i=0;i<32;i++){
      for(const enabled of(i%2?[true,false]:[false,true]))samples[enabled?'candidate':'baseline'].push(measure(enabled))
      await new Promise(r=>setTimeout(r,0))
    }
    fast=false
    if(!calls.every(({grid,args},i)=>JSON.stringify(range.apply(grid,args))===reference[i]))throw Error('Reference drift')
    return {snapshot,queries:calls.map(({grid,args},i)=>({args,config:grid.config,sectorCount:JSON.parse(reference[i]).length})),statsByMode,repetitions,samples,
      summary:{baseline:stats(samples.baseline),candidate:stats(samples.candidate)},
      caveat:'Frozen real scene grid queries, original code except temporary most-recent lookup shortcut. CPU only, no per-frame GPU/FPS speed claim. JSON values and order compared exactly; LRU behavior needs separate regression tests before production change.'}
  }finally{SectorGrid.prototype.getSectorsInRange=range;SectorGrid.prototype.layerAt=lookup;engine.start()}
}

